// Probe: does a bash child trap SIGINT when spawned from a dart process
// in three signal-disposition states: no-watch / watch / watch-then-cancel.
Future<void> main(List<String> args) async {
  final mode = args.isNotEmpty ? args[0] : 'none';
  StreamSubscription<ProcessSignal>? sub;
  if (mode == 'watch' || mode == 'watch-cancelled') {
    sub = ProcessSignal.sigint.watch().listen((_) {});
  }
  if (mode == 'watch-cancelled') {
    await sub!.cancel();
  }
  final p = await Process.start('bash', [
    '-c',
