  ]);
  final ready = Completer<void>();
  p.stdout.transform(utf8.decoder).listen((c) {
    if (!ready.isCompleted && c.contains('READY')) ready.complete();
  });
  await ready.future;
  await Future<void>.delayed(const Duration(milliseconds: 200));
  final ok = p.kill(ProcessSignal.sigint);
  int code;
  try {
    code = await p.exitCode.timeout(
      const Duration(seconds: 5),
      onTimeout: () => -1,
    );
  } catch (_) {
    code = -2;
  }
  stdout.writeln('mode=$mode killDelivered=$ok bashExit=$code');
  exit(0);
}

