      p.stdout.transform(utf8.decoder).listen((c) {
        if (!ready.isCompleted && c.contains('READY')) ready.complete();
      });
      await ready.future;
      await Future<void>.delayed(const Duration(milliseconds: 100));
      p.kill(ProcessSignal.sigint);
      try {
        return await p.exitCode.timeout(
          const Duration(seconds: 5),
          onTimeout: () => -1,
        );
      } catch (_) {
        return -2;
      }
    });
    if (res != 130) wedged++;
    stdout.writeln('round $i: bashExit=$res');
  }
  stdout.writeln('wedged=$wedged/$rounds');
  exit(0);
}

