import 'dart:async';
import 'dart:io';
import 'dart:isolate';

String sigmasks() {
  final status = File('/proc/self/status').readAsStringSync();
  final lines = status
      .split('\n')
      .where((l) => l.startsWith('SigBlk') || l.startsWith('SigIgn') || l.startsWith('SigCgt'))
      .toList();
  return lines.join(' | ');
}

Future<String> childMasks() async {
  final res = await Process.run('bash', ['-c', 'grep -E "^(SigBlk|SigIgn|SigCgt)" /proc/self/status']);
  return res.stdout.toString().trim().replaceAll('\n', ' | ');
}

Future<void> main(List<String> args) async {
  stdout.writeln('main  (spawn-parent): ${sigmasks()}');
  stdout.writeln('main  (child bash)  : ${await childMasks()}');
  await Isolate.run(() async {});
  final isoMasks = await Isolate.run(() async {
    // Force this to run on a thread-pool worker; report masks from there.
    return File('/proc/self/status').readAsStringSync();
  });
  final isoLines = isoMasks
      .split('\n')
      .where((l) => l.startsWith('SigBlk') || l.startsWith('SigIgn') || l.startsWith('SigCgt'))
      .join(' | ');
  stdout.writeln('isolate (parent)    : $isoLines');
  final childIso = await Isolate.run(() async => (await Process.run(
        'bash',
        ['-c', 'grep -E "^(SigBlk|SigIgn|SigCgt)" /proc/self/status'],
      )).stdout.toString().trim().replaceAll('\n', ' | '));
  stdout.writeln('isolate (child bash): $childIso');

  // With an ACTIVE sigint watch (dart installs a handler):
  final sub = ProcessSignal.sigint.watch().listen((_) {});
  await Future<void>.delayed(const Duration(milliseconds: 100));
  stdout.writeln('watch  (parent)     : ${sigmasks()}');
  stdout.writeln('watch  (child bash) : ${await childMasks()}');
  await sub.cancel();
  await Future<void>.delayed(const Duration(milliseconds: 100));
  stdout.writeln('cancel (parent)     : ${sigmasks()}');
  stdout.writeln('cancel (child bash) : ${await childMasks()}');
}

